WITH ended_lessons AS (SELECT school_uid,course_id,class_id FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND class_status=3 AND school_uid>0 GROUP BY school_uid,course_id,class_id), mappings AS (SELECT l.school_uid,l.course_id,l.class_id,COUNT(DISTINCT a.category_id) AS categories_n FROM ended_lessons l LEFT JOIN eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a ON a.school_uid=l.school_uid AND a.course_id=l.course_id AND a.biz_id=l.class_id AND a.dt='2026-09-11' AND a.biz_type=1 AND a.is_deleted=0 AND a.publish_flag=2 AND a.category_id>0 AND a.start_time>=1788537600 AND a.start_time<1789142400 GROUP BY l.school_uid,l.course_id,l.class_id) SELECT COUNT(1) AS ended_lesson_n,COUNT(DISTINCT school_uid) AS ended_school_n,SUM(CASE WHEN categories_n>0 THEN 1 ELSE 0 END) AS mapped_lesson_n,SUM(CASE WHEN categories_n=0 THEN 1 ELSE 0 END) AS unmapped_lesson_n,SUM(CASE WHEN categories_n>1 THEN 1 ELSE 0 END) AS multi_category_lesson_n FROM mappings
